docker compose exec -T db psql -U ecommerce -d ecommerce <<'SQL'
\echo '=== item frequency spread (the skew that makes the CP4 top-3 unambiguous) ==='
SELECT i.item_name, count(DISTINCT ti.transaction_id) AS times_bought
FROM items i JOIN transaction_items ti USING (item_id)
GROUP BY i.item_id, i.item_name ORDER BY times_bought DESC, i.item_id LIMIT 6;

\echo ''
\echo '=== sequences usable after the seed: insert one real row, check the id ==='
BEGIN;
INSERT INTO items (item_name, manufacturer_name, cost, weight_kg)
VALUES ('Post-Seed Probe','Acme',1.00,1.000) RETURNING item_id;
ROLLBACK;
SQL

