input.command:
docker compose exec -T db psql -U ecommerce -d ecommerce <<'SQL'
BEGIN;
\echo '-- bulk-load 200k extra transactions (no line items, so the trigger stays idle)'
INSERT INTO transactions (membership_id, transaction_ts)
SELECT m.membership_id, TIMESTAMPTZ '2026-06-20 00:00+00' + (g % 7776000) * INTERVAL '1 second'
FROM generate_series(1, 200000) g
JOIN LATERAL (SELECT membership_id FROM members ORDER BY membership_id OFFSET (g % 50) LIMIT 1) m ON TRUE;
ANALYZE transactions;

\echo ''
\echo '-- same selective lookup, now at 200k rows:'
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF)
SELECT * FROM transactions WHERE membership_id = 'Murphy_0851c';

\echo ''
\echo '-- and the date-range index:'
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF)
SELECT count(*) FROM transactions WHERE transaction_ts >= TIMESTAMPTZ '2026-09-01' AND transaction_ts < TIMESTAMPTZ '2026-09-02';
ROLLBACK;
SQL

